(function() {
    'use strict';

    class UNADAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'UNAD Productividad y Teletrabajo';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefKey: 'round1_brief'
                },
                {
                    titleKey: 'round2_title',
                    briefKey: 'round2_brief'
                },
                {
                    titleKey: 'round3_title',
                    briefKey: 'round3_brief'
                },
                {
                    titleKey: 'round4_title',
                    briefKey: 'round4_brief'
                }
            ];

            this.BUDGET_CAP = 150;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budgetCap: 150,
                    budgetUsed: 0,
                    totalInvested: 0,
                    responseTime: 16.0,
                    burnoutPct: 48,
                    satisfaction: 66,
                    menCompliance: 65,
                    stressCost: 340,
                    nightActivityPct: 34,
                    responseTimeHistory: [16.0],
                    menComplianceHistory: [65],
                    satisfactionHistory: [66],
                    burnoutHistory: [48],
                    profitHistory: [],
                    salesHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    measurementPhilosophy: 'outputs',
                    coreHoursPolicy: '4hours',
                    disconnectionLaw: 'yes',
                    investTools: 40,
                    investTraining: 30,
                    investWellbeing: 40,
                    investConnectivity: 40
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 100);
            setTimeout(function() { self._attachLiveBudget(); }, 200);
        }

        _attachLiveBudget() {
            var ids = ['investTools','investTraining','investWellbeing','investConnectivity'];
            var self = this;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el && !el.dataset.budgetListener) {
                    el.addEventListener('input', function() { self._refreshBudgetDisplay(); });
                    el.dataset.budgetListener = '1';
                }
            });
            this._refreshBudgetDisplay();
        }

        _refreshBudgetDisplay() {
            var t = this._num('investTools');
            var tr = this._num('investTraining');
            var w = this._num('investWellbeing');
            var c = this._num('investConnectivity');
            var total = t + tr + w + c;
            var disp = document.getElementById('allocatedDisplay');
            var cap = document.getElementById('budgetCapDisplay');
            var box = document.querySelector('.unad-sim-budget-total');
            if (disp) disp.textContent = total;
            if (cap) cap.textContent = this.BUDGET_CAP;
            if (box) {
                if (total > this.BUDGET_CAP) box.classList.add('over');
                else box.classList.remove('over');
            }
        }

        _num(id) {
            var el = document.getElementById(id);
            if (!el) return 0;
            var v = parseFloat(el.value);
            return isNaN(v) ? 0 : v;
        }

        validateDecisions(decisions) {
            var measurement = document.getElementById('measurementPhilosophy');
            var coreHours = document.getElementById('coreHoursPolicy');
            var disconnection = document.getElementById('disconnectionLaw');

            if (measurement) decisions.measurementPhilosophy = measurement.value;
            if (coreHours) decisions.coreHoursPolicy = coreHours.value;
            if (disconnection) decisions.disconnectionLaw = disconnection.value;

            decisions.investTools = this._num('investTools');
            decisions.investTraining = this._num('investTraining');
            decisions.investWellbeing = this._num('investWellbeing');
            decisions.investConnectivity = this._num('investConnectivity');

            var total = decisions.investTools + decisions.investTraining +
                        decisions.investWellbeing + decisions.investConnectivity;

            if (total > this.BUDGET_CAP) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('err_over_budget'), 'warning'
                );
                return false;
            }
            if (total <= 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('err_no_invest'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var measurementMap = {
                'outputs': 1.30,
                'inputs_light': 1.00,
                'surveillance': 0.70
            };
            var coreMap = {
                'none': 1.00,
                '4hours': 0.78,
                '6hours': 0.88,
                '8hours': 0.98
            };
            var measMul = measurementMap[d.measurementPhilosophy] || 1.0;
            var coreMul = coreMap[d.coreHoursPolicy] || 1.0;
            var discBonus = (d.disconnectionLaw === 'yes') ? 1 : 0;

            var toolsEff = d.investTools * 0.012;
            var trainEff = d.investTraining * 0.010;
            var wellEff = d.investWellbeing * 0.011;
            var connEff = d.investConnectivity * 0.014;

            var newResponseTime = ds.responseTime * coreMul;
            newResponseTime -= toolsEff * 1.8;
            newResponseTime -= trainEff * 1.4;
            newResponseTime -= connEff * 0.9;
            newResponseTime = newResponseTime / measMul;
            newResponseTime = Math.max(2.5, newResponseTime);

            var newBurnout = ds.burnoutPct;
            newBurnout -= wellEff * 6.5;
            newBurnout -= trainEff * 2.5;
            newBurnout -= discBonus * 7;
            if (d.measurementPhilosophy === 'surveillance') newBurnout += 12;
            if (d.coreHoursPolicy === '8hours') newBurnout += 4;
            if (d.coreHoursPolicy === '4hours') newBurnout -= 3;
            newBurnout = Math.max(6, Math.min(85, newBurnout));

            var responseGain = Math.max(0, (ds.responseTime - newResponseTime));
            var newSatisfaction = ds.satisfaction + (responseGain * 1.8) + (connEff * 2.0);
            if (d.measurementPhilosophy === 'surveillance') newSatisfaction -= 3;
            newSatisfaction = Math.max(35, Math.min(98, newSatisfaction));

            var newStress = ds.stressCost;
            newStress -= wellEff * 22;
            newStress -= discBonus * 18;
            if (d.measurementPhilosophy === 'surveillance') newStress += 45;
            if (d.coreHoursPolicy === '8hours') newStress += 15;
            newStress = Math.max(90, Math.min(420, newStress));

            var newMenCompliance = 60 + (24 - newResponseTime) * 2.8 + connEff * 3.2 + (newSatisfaction - 66) * 0.4;
            newMenCompliance = Math.max(40, Math.min(99, newMenCompliance));

            var newNightActivity = ds.nightActivityPct * coreMul - (discBonus * 5) - (trainEff * 3);
            newNightActivity = Math.max(4, Math.min(60, newNightActivity));

            var investedThisRound = d.investTools + d.investTraining + d.investWellbeing + d.investConnectivity;
            ds.totalInvested += investedThisRound;
            ds.budgetUsed = investedThisRound;

            ds.responseTime = Math.round(newResponseTime * 10) / 10;
            ds.burnoutPct = Math.round(newBurnout);
            ds.satisfaction = Math.round(newSatisfaction);
            ds.menCompliance = Math.round(newMenCompliance);
            ds.stressCost = Math.round(newStress);
            ds.nightActivityPct = Math.round(newNightActivity);

            ds.responseTimeHistory.push(ds.responseTime);
            ds.menComplianceHistory.push(ds.menCompliance);
            ds.satisfactionHistory.push(ds.satisfaction);
            ds.burnoutHistory.push(ds.burnoutPct);

            var matriculasAtRisk = 85000;
            var rescueFactor = Math.max(0, (ds.menCompliance - 65) / 30);
            var rescuedRevenue = matriculasAtRisk * Math.min(1, rescueFactor);
            var stressSavings = Math.max(0, 340 - ds.stressCost);
            var quarterlyBenefit = (rescuedRevenue / 4) + stressSavings;
            var roiRatio = ds.totalInvested > 0 ? (quarterlyBenefit / ds.totalInvested) : 0;

            ds.profitHistory.push(Math.round(quarterlyBenefit));
            ds.salesHistory.push(ds.menCompliance);

            var self = this;
            // v1.1.0 FIX: capture nextPeriod BEFORE the async. The host increments
            // state.currentPeriod synchronously after calculateResults() returns, so reading it
            // inside the timer was two quarters ahead — quarters 2-3 showed the wrong briefing.
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
                self._refreshBudgetDisplay();
            }, 400);

            return {
                period: state.currentPeriod,
                responseTime: ds.responseTime,
                burnoutPct: ds.burnoutPct,
                satisfaction: ds.satisfaction,
                menCompliance: ds.menCompliance,
                stressCost: ds.stressCost,
                investedThisRound: investedThisRound,
                totalInvested: ds.totalInvested,
                quarterlyBenefit: Math.round(quarterlyBenefit),
                roiRatio: Math.round(roiRatio * 100) / 100
            };
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var tFn = window.mySimulation && window.mySimulation.t ?
                window.mySimulation.t.bind(window.mySimulation) :
                function(k) { return k; };

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var roundTitleEl = document.getElementById('roundTitle');

            if (titleEl) titleEl.textContent = tFn(round.titleKey);
            if (textEl) textEl.innerHTML = tFn(round.briefKey);
            if (roundTitleEl) roundTitleEl.textContent = tFn(round.titleKey);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budgetCap',
                (v) => 'COP ' + v + 'M');
            uiManager.bind('responseTimeDisplay', 'domainState.responseTime',
                (v) => (Math.round(v * 10) / 10).toFixed(1) + ' h');
            uiManager.bind('burnoutDisplay', 'domainState.burnoutPct',
                (v) => v + '%');
            uiManager.bind('satisfactionDisplay', 'domainState.satisfaction',
                (v) => v + '%');
            uiManager.bind('menDisplay', 'domainState.menCompliance',
                (v) => v + '%');
            uiManager.bind('stressDisplay', 'domainState.stressCost',
                (v) => 'COP ' + v + 'M');

            // v1.1.0 FIX: re-sync sim-owned briefing + budget display after an Undo.
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn && !undoBtn._unUndoBound) {
                undoBtn._unUndoBound = true;
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        self._updateBriefing(window.mySimulation.state);
                        self._refreshBudgetDisplay();
                    }, 60);
                });
            }
        }

        getChartConfig() {
            return {
                responseTimeChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Tiempo de respuesta (h)',
                                data: [],
                                borderColor: '#3b82f6',
                                backgroundColor: 'rgba(59,130,246,0.15)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Burnout tutores (%)',
                                data: [],
                                borderColor: '#dc2626',
                                backgroundColor: 'rgba(220,38,38,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Tiempo de Respuesta y Burnout', color: '#0f172a', font: { size: 14, weight: 'bold' } },
                            legend: { labels: { color: '#334155' } }
                        },
                        scales: {
                            y: { type: 'linear', position: 'left', beginAtZero: true, title: { display: true, text: 'Horas', color: '#3b82f6' }, ticks: { color: '#334155' } },
                            y1: { type: 'linear', position: 'right', beginAtZero: true, max: 100, title: { display: true, text: '% Burnout', color: '#dc2626' }, ticks: { color: '#334155' }, grid: { drawOnChartArea: false } },
                            x: { ticks: { color: '#334155' } }
                        }
                    }
                },
                menComplianceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Cumplimiento MEN (%)',
                                data: [],
                                borderColor: '#f59e0b',
                                backgroundColor: 'rgba(245,158,11,0.18)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3
                            },
                            {
                                label: 'Satisfacción estudiantil (%)',
                                data: [],
                                borderColor: '#0d9488',
                                backgroundColor: 'rgba(13,148,136,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cumplimiento MEN y Satisfacción', color: '#0f172a', font: { size: 14, weight: 'bold' } },
                            legend: { labels: { color: '#334155' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#334155' } },
                            x: { ticks: { color: '#334155' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.responseTimeHistory.map(function(_, i) {
                return i === 0 ? 'Baseline' : 'T' + i;
            });
            return {
                responseTimeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.responseTimeHistory },
                        { data: ds.burnoutHistory }
                    ]
                },
                menComplianceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.menComplianceHistory },
                        { data: ds.satisfactionHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.responseTime > 24) return window.mySimulation.t('hint_men_risk');
            if (results.burnoutPct > 45) return window.mySimulation.t('hint_burnout');
            if (state.decisions.measurementPhilosophy === 'surveillance') return window.mySimulation.t('hint_surveillance');
            if (state.decisions.coreHoursPolicy === '8hours') return window.mySimulation.t('hint_8hours');
            if (state.decisions.investConnectivity < 20) return window.mySimulation.t('hint_connectivity');
            if (state.decisions.investWellbeing < 20) return window.mySimulation.t('hint_wellbeing');
            if (results.menCompliance >= 90 && results.burnoutPct < 20) return window.mySimulation.t('hint_excellent');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.coreHoursPolicy', label: 'Core Hours', i18nKey: 'col_core' },
                { key: 'decisions.measurementPhilosophy', label: 'Medición', i18nKey: 'col_measurement' },
                { key: 'results.investedThisRound', label: 'Inversión', i18nKey: 'col_invested', formatter: (v) => 'COP ' + v + 'M' },
                { key: 'results.responseTime', label: 'Respuesta', i18nKey: 'col_response', formatter: (v) => v + ' h' },
                { key: 'results.burnoutPct', label: 'Burnout', i18nKey: 'col_burnout', formatter: (v) => v + '%' },
                { key: 'results.menCompliance', label: 'MEN', i18nKey: 'col_men', formatter: (v) => v + '%' },
                { key: 'results.satisfaction', label: 'Satisfacción', i18nKey: 'col_satisfaction', formatter: (v) => v + '%' }
            ];
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = (last && last.results) || {};
            var menFinal = r.menCompliance || 0;
            var burnoutFinal = r.burnoutPct || 0;
            var satFinal = r.satisfaction || 0;
            var respFinal = r.responseTime || 99;
            var totalInvested = r.totalInvested || 0;
            var matriculasAtRisk = 85000;
            var rescueFactor = Math.max(0, Math.min(1, (menFinal - 65) / 30));
            var rescuedRevenue = matriculasAtRisk * rescueFactor;
            var roi = totalInvested > 0 ? Math.round(rescuedRevenue / totalInvested) : 0;

            var performance = 'Principiante';
            var insights = [];
            var score = 0;
            if (menFinal >= 90) score += 2; else if (menFinal >= 80) score += 1;
            if (burnoutFinal <= 20) score += 2; else if (burnoutFinal <= 30) score += 1;
            if (satFinal >= 85) score += 2; else if (satFinal >= 75) score += 1;
            if (respFinal <= 4) score += 2; else if (respFinal <= 8) score += 1;

            if (score >= 7) performance = 'Excelente';
            else if (score >= 5) performance = 'Bueno';
            else if (score >= 3) performance = 'Aceptable';

            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            if (menFinal >= 95) insights.push(t('ins_men_secured'));
            else if (menFinal < 80) insights.push(t('ins_men_risk'));

            if (burnoutFinal <= 20) insights.push(t('ins_burnout_good'));
            else if (burnoutFinal >= 40) insights.push(t('ins_burnout_bad'));

            if (respFinal <= 4) insights.push(t('ins_resp_good'));
            if (respFinal > 12) insights.push(t('ins_resp_bad'));

            insights.push(t('ins_roi').replace('{roi}', roi).replace('{rescued}', Math.round(rescuedRevenue)).replace('{invested}', totalInvested));

            return {
                totalInvested: totalInvested,
                menCompliance: menFinal,
                burnout: burnoutFinal,
                satisfaction: satFinal,
                responseTime: respFinal,
                roi: roi,
                performance: performance,
                insights: insights
            };
        }

